INTL_WORK=re.compile(r'jobs|jobseekers|JobsPH|AntiworkPH',re.I)
def scope(c):
    if BAY_PAT.match(c): return 'BAY'
    if c in WORK_GEN: return 'WORK_GEN'
    if re.search(r'^(AIJobs|AIdaily_news|AINewsAndTrends|HandshakeAi_jobs)$',c): return 'AI_TOPIC_SUBS'
    if re.search(r'jobs|jobseek|Jobs|antiwork',c,re.I): return 'JOBS_OTHER_NICHE_OR_INTL'
    return 'GENERAL_OTHER'
